export const fetchNodeContent = async ({
  client,
  spaceId,
  nodeInstanceId,
  variant,
}: {
  client: DGSupabaseClient;
  spaceId: number;
  nodeInstanceId: string;
  variant: "direct" | "full";
}): Promise<string | null> => {
  const { data, error } = await client
    .from("my_contents")
    .select("text")
    .eq("source_local_id", nodeInstanceId)
    .eq("space_id", spaceId)
    .eq("variant", variant)
    .maybeSingle();

  if (error || !data || data.text == null) {
    console.error(
      `Error fetching node content (${variant}):`,
      error || "No data",
    );
    return null;
  }

  return data.text;
};

export const fetchNodeContentWithMetadata = async ({
  client,
  spaceId,
  nodeInstanceId,
  variant,
}: {
  client: DGSupabaseClient;
  spaceId: number;
  nodeInstanceId: string;
  variant: "direct" | "full";
}): Promise<{
  content: string;
  createdAt: number;
  modifiedAt: number;
} | null> => {
  const { data, error } = await client
    .from("my_contents")
    .select("text, created, last_modified")
    .eq("source_local_id", nodeInstanceId)
    .eq("space_id", spaceId)
    .eq("variant", variant)
    .maybeSingle();

  if (error || !data || data.text == null) {
    console.error(
      `Error fetching node content with metadata (${variant}):`,
      error || "No data",
    );
    return null;
  }

  return {
    content: data.text,
    createdAt: data.created ? new Date(data.created + "Z").valueOf() : 0,
    modifiedAt: data.last_modified
      ? new Date(data.last_modified + "Z").valueOf()
      : 0,
  };
};

